text(await tools.apply_patch("*** Begin Patch
*** Add File: /Volumes/aro/projects/prose_generation/enrichment/bible/work/s001/ehlikitap-images.sol.max.session-20261005/sec11/verdicts.jsonl
+{"connection_id":"BC-f83eedfee1991ac08cec","ref":"Augustine, Confessions 10.29.40","status":"unavailable","reason":"Confessions passage is absent from this local snapshot; the claimed wording cannot be checked.","paragraphs":[],"evidence":[],"annotations":[]}
+{"connection_id":"BC-d7ffc61ffe26b82abee7","ref":"Augustine, Confessions 10.29.40","status":"unavailable","reason":"Augustine's interpretation is not in the available local witness, so its wording and context remain unverified.","paragraphs":[],"evidence":[],"annotations":[]}
+{"connection_id":"BC-c373b54b6d30b6748816","ref":"Augustine, Quaestiones Evangeliorum 2.19","status":"unavailable","reason":"The cited Augustine work is absent from the local snapshot; its Samaritan reading cannot be verified.","paragraphs":[],"evidence":[],"annotations":[]}
+{"connection_id":"BC-b28fab847650a9de78af","ref":"Didache 1.1","status":"unavailable","reason":"Didache 1.1 is absent from the local snapshot; the two-ways wording was not checked.","paragraphs":[],"evidence":[],"annotations":[]}
+{"connection_id":"BC-f2c71fc9fe210be737e4","ref":"Didache 1:1","status":"unavailable","reason":"Didache 1:1 is absent from the local snapshot; this separate locator remains unverified.","paragraphs":[],"evidence":[],"annotations":[]}
+{"connection_id":"BC-f81ffc32145dec89693d","ref":"Didache 1:5","status":"unavailable","reason":"Didache 1:5 is absent from the local snapshot; the proposed giving command was not checked.","paragraphs":[],"evidence":[],"annotations":[]}
+{"connection_id":"BC-2dcf4b7203dc6a787f1c","ref":"SBLGNT:1Cor.12.22","status":"rejected","reason":"The verse calls weaker body members indispensable, but does not depict supporting a stranded walker; Mark 2:3 supplies that concrete act.","paragraphs":[],"evidence":["SBLGNT:1Cor.12.22"],"annotations":[]}
+{"connection_id":"BC-0ac6d2f26a840a4ee6c0","ref":"SBLGNT:1Pet.5.10","status":"rejected","reason":"The four verbs describe believers' restoration after suffering, with no wall, pillar or walking image in the verse.","paragraphs":[],"evidence":["SBLGNT:1Pet.5.10"],"annotations":[]}
+{"connection_id":"BC-73173e2793af6c05dc51","ref":"SBLGNT:1Thess.5.14","status":"rejected","reason":"Holding fast to the weak is ethical counsel, but does not describe the bodily support pictured more exactly in Mark 2:3.","paragraphs":[],"evidence":["SBLGNT:1Thess.5.14"],"annotations":[]}
+{"connection_id":"BC-23cd774b8d577527c86d","ref":"SBLGNT:1Thess.5.14","status":"rejected","reason":"Patience follows care for the weak, but the text does not connect that patience to an unhurried gait.","paragraphs":[],"evidence":["SBLGNT:1Thess.5.14"],"annotations":[]}
+{"connection_id":"BC-d104362d852fbb1f335b","ref":"SBLGNT:1Tim.3.15","status":"rejected","reason":"The church as pillar of truth is an institutional metaphor; it does not add to the traveler's support or restored steps.","paragraphs":[],"evidence":["SBLGNT:1Tim.3.15"],"annotations":[]}
+{"connection_id":"BC-174e7e813d00cefd40b9","ref":"SBLGNT:2Cor.12.9","status":"rejected","reason":"Power in weakness is a broad theological parallel without the requested help, straight way or bodily raising in this verse.","paragraphs":[],"evidence":["SBLGNT:2Cor.12.9"],"annotations":[]}
+{"connection_id":"BC-67ea58f70f893f36ba6b","ref":"SBLGNT:2Tim.4.17","status":"rejected","reason":"The Lord strengthens Paul for proclamation, a different purpose and setting from the stranded walk.","paragraphs":[],"evidence":["SBLGNT:2Tim.4.17"],"annotations":[]}
+{"connection_id":"BC-fb8f9065d987e8600a3e","ref":"SBLGNT:Acts.14.10","status":"rejected","reason":"Standing and walking follow Paul's command, but Acts 3:7-8 also shows a supporting hand, making the latter more exact here.","paragraphs":[],"evidence":["SBLGNT:Acts.14.10"],"annotations":[]}
+{"connection_id":"BC-3479933a7defc08148aa","ref":"SBLGNT:Acts.16.9","status":"rejected","reason":"The plea asks Paul to cross to Macedonia for communal aid; it says nothing of impaired walking or bodily support.","paragraphs":[],"evidence":["SBLGNT:Acts.16.9"],"annotations":[]}
+{"connection_id":"BC-11f86bf3e457268a0e9b","ref":"SBLGNT:Acts.17.31","status":"rejected","reason":"The fixed judgment day is real, but paragraph 56 uses malik for the support image rather than explaining judgment; Isaiah 33:22 joins rule to rescue more closely.","paragraphs":[],"evidence":["SBLGNT:Acts.17.31"],"annotations":[]}
+{"connection_id":"BC-bb33613a515e8790a9e0","ref":"SBLGNT:Acts.20.35","status":"rejected","reason":"The duty to aid the weak is explicit but does not present the two-sided or hand-held movement of the selected scenes.","paragraphs":[],"evidence":["SBLGNT:Acts.20.35"],"annotations":[]}
+{"connection_id":"BC-1da17c7012a6af36859c","ref":"SBLGNT:Acts.27.17","status":"rejected","reason":"The Greek help noun refers to ropes undergirding a ship, not a human body or a request for divine aid.","paragraphs":[],"evidence":["SBLGNT:Acts.27.17"],"annotations":[]}
+{"connection_id":"BC-0274cad7bbdf307c37a7","ref":"SBLGNT:Acts.3.7","status":"accepted","reason":"Peter takes the man's hand and raises him as his feet strengthen; paired verse 8 completes the walking sequence.","paragraphs":[56],"evidence":["SBLGNT:Acts.3.7","SBLGNT:Acts.3.8"],"annotations":["S001-INC-MTF-003"]}
+{"connection_id":"BC-793a1eb62a4d5105e640","ref":"SBLGNT:Acts.3.7","status":"accepted","reason":"The explicit right hand, raising, and strengthened feet give the described physical support.","paragraphs":[56],"evidence":["SBLGNT:Acts.3.7","SBLGNT:Acts.3.8"],"annotations":["S001-INC-MTF-003"]}
+{"connection_id":"BC-8b9c1d5332b28b14dfc4","ref":"SBLGNT:Acts.3.8","status":"accepted","reason":"The man stands and walks after the hand-assisted raising in verse 7.","paragraphs":[56],"evidence":["SBLGNT:Acts.3.7","SBLGNT:Acts.3.8"],"annotations":["S001-INC-MTF-003"]}
+{"connection_id":"BC-f89130ccd935b7011ceb","ref":"SBLGNT:Acts.8.31","status":"rejected","reason":"The official needs help interpreting Isaiah, but the passage shifts from bodily travel and walking to reading.","paragraphs":[],"evidence":["SBLGNT:Acts.8.31"],"annotations":[]}
+{"connection_id":"BC-03c4275bc0589eb49f34","ref":"SBLGNT:Acts.8.31","status":"rejected","reason":"Philip's guidance in a chariot concerns interpretation of a text; no impaired gait or straight road appears.","paragraphs":[],"evidence":["SBLGNT:Acts.8.31"],"annotations":[]}
+{"connection_id":"BC-f9f6759645ef1c215466","ref":"SBLGNT:Col.1.11","status":"rejected","reason":"Strength for patience is inward ethical endurance and lacks the bodily path motif of paragraphs 55-58.","paragraphs":[],"evidence":["SBLGNT:Col.1.11"],"annotations":[]}
+{"connection_id":"BC-8e00d43cfb5424c856ed","ref":"SBLGNT:Col.2.7","status":"rejected","reason":"Rooted and built up describes faith in Christ, but the verse does not pair a standing tree with a damaged wall or travel.","paragraphs":[],"evidence":["SBLGNT:Col.2.7"],"annotations":[]}
